const key = msg.camKey;
if (!key) return null;
const st = flow.get('camStatus') || {};
if (st[key]) {
  st[key].img = msg.payload.toString('base64');
  flow.set('camStatus', st);
}
return null;

const key='play2';
const payload=msg.payload;
const size=payload?payload.length:0;
const minSize=3000;
const st=flow.get('camStatus')||{};
if(!st[key])st[key]={name:'Play2',key:key,lastUpdate:null,lastSize:null,status:'unknown',error:null,img:''};
if(size<minSize){
  st[key].status='error'; st[key].error='stdout '+size+'B';
  flow.set('camStatus',st);
  node.status({fill:'red',shape:'ring',text:'error: '+size+'B'});
  if(!msg._retry){msg._retry=true;return[null,msg];}
  return null;
}
st[key].status='ok'; st[key].lastUpdate=Date.now(); st[key].lastSize=size; st[key].error=null;
flow.set('camStatus',st);
node.status({fill:'green',shape:'dot',text:'OK ~'+Math.round(size/1024)+'KB'});
msg.camKey=key;
return[msg,null];

